<style>
.sf-page{max-width:1450px;margin:auto}.sf-heading{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap;margin-bottom:24px}.sf-heading h2{font-size:25px;margin:0 0 6px}.sf-heading p{color:#66738b;font-size:13px;margin:0}.sf-panel{background:#fff;border:1px solid #e5eaf3;border-radius:15px;padding:21px;margin-bottom:20px;box-shadow:0 3px 16px #17223b07}.sf-panel h3{font-size:16px;margin:0 0 17px}.sf-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.sf-field{display:flex;flex-direction:column;gap:7px;min-width:0}.sf-field span{font-size:12px;font-weight:700;color:#42516c}.sf-field input,.sf-field select{width:100%;min-height:43px;border:1px solid #dbe2ee;border-radius:9px;padding:9px 11px;background:#fff;color:#17223b}.sf-field input:focus,.sf-field select:focus{outline:2px solid #c7d2fe}.sf-actions{display:flex;gap:10px;flex-wrap:wrap;align-items:end;margin-top:16px}.sf-btn{display:inline-flex;align-items:center;justify-content:center;border-radius:9px;border:1px solid #d9def0;padding:10px 15px;font-size:12px;font-weight:750;background:white;color:#3730a3;cursor:pointer;text-decoration:none}.sf-btn-primary{background:#4f46e5;color:white;border-color:#4f46e5}.sf-btn-danger{color:#b91c1c;border-color:#fecaca}.sf-scroll{overflow-x:auto}.sf-table{width:100%;min-width:1050px;border-collapse:collapse}.sf-table th{background:#f4f6fb;color:#52617b;font-size:11px;text-transform:uppercase;letter-spacing:.4px;text-align:left;padding:13px}.sf-table td{padding:14px 13px;border-bottom:1px solid #edf0f5;font-size:12px;vertical-align:middle}.sf-table tr:last-child td{border-bottom:0}.sf-money{font-variant-numeric:tabular-nums;white-space:nowrap;font-weight:700}.sf-muted{color:#66738b}.sf-tag{display:inline-block;background:#eef2ff;color:#4338ca;padding:6px 9px;border-radius:7px;font-weight:700}.sf-inline{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.sf-inline input,.sf-inline select{min-height:35px;border:1px solid #dbe2ee;border-radius:7px;padding:5px 7px;max-width:160px}.sf-inline button{min-height:35px}.sf-empty{text-align:center;padding:25px!important;color:#66738b}.sf-note{font-size:12px;color:#66738b;margin:12px 0}.sf-summary{display:flex;gap:12px;flex-wrap:wrap;margin:12px 0}.sf-summary span{padding:8px 12px;background:#f4f6fb;border-radius:8px;font-size:12px}.sf-form{max-width:1050px}.sf-form .sf-grid{grid-template-columns:repeat(2,minmax(0,1fr))}@media(max-width:1050px){.sf-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.sf-grid,.sf-form .sf-grid{grid-template-columns:1fr}.sf-panel{padding:15px}.sf-heading h2{font-size:21px}.sf-btn{width:auto}}
</style>
